#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Local restrict-qualified aliases to help the compiler with
     alias analysis and enable better vectorization.  The PolyBench
     framework guarantees that these arrays do not overlap. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE * restrict b_ = b;
  DATA_TYPE * restrict x_ = x;
  DATA_TYPE * restrict y_ = y;

  for (i = 0; i < n; i++)
    {
      x_[i] = 0;
      y_[i] = 0;
      b_[i] = (i+1)/fn/2.0 + 4;
    }

  for (i = 0; i < n; i++)
    {
      DATA_TYPE * restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;

      for (j = i+1; j < n; j++)
	Ai[j] = 0;

      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T.
     Not necessary for LU itself, but kept for consistency with
     the original PolyBench/Cholesky initialization. */
  int r;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (* restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T.
     - Outer loop over r writes independent rows of B.
     - Each (r,s) entry is computed as a dot product over t.
     This improves cache locality and keeps each accumulation
     in a register instead of repeatedly loading/storing B. */
#if defined(_OPENMP)
#pragma omp parallel for schedule(static)
#endif
  for (r = 0; r < n; ++r)
    {
      int s, t;
      DATA_TYPE * restrict Br = B_[r];
      DATA_TYPE * restrict Ar = A_[r];

      for (s = 0; s < n; ++s)
        {
          const DATA_TYPE * restrict As = A_[s];
          DATA_TYPE sum = (DATA_TYPE)0;

          for (t = 0; t < n; ++t)
            sum += Ar[t] * As[t];

          Br[s] = sum;
        }
    }

  /* Copy the SPD matrix back into A.
     Row-wise memcpy exposes bulk-copy semantics and contiguous
     memory to the optimizer and libc. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE * restrict Ar = A_[r];
      DATA_TYPE * restrict Br = B_[r];
      memcpy(Ar, Br, (size_t)n * sizeof(DATA_TYPE));
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

  /* Local restrict-qualified aliases for better optimization. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE * restrict b_ = b;
  DATA_TYPE * restrict x_ = x;
  DATA_TYPE * restrict y_ = y;

#pragma scop
  /* LU factorization (in-place, no pivoting). */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE * restrict Ai = A_[i];
    int j;

    /* Compute elements of L in row i (columns 0..i-1). */
    for (j = 0; j < i; j++) {
      DATA_TYPE w = Ai[j];
      int k;

      /* This loop carries a true dependence on w; we keep the
         original iteration order while making memory accesses
         explicit and cache-friendly. */
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A_[k][j];
      }

      Ai[j] = w / A_[j][j];
    }

    /* Compute elements of U in row i (columns i..N-1).
       For a fixed i, each column j is independent, so this
       loop can be parallelized across j when OpenMP is enabled. */
#if defined(_OPENMP)
#pragma omp parallel for schedule(static)
#endif
    for (j = i; j < _PB_N; j++) {
      DATA_TYPE w = Ai[j];
      int k;

      for (k = 0; k < i; k++) {
        w -= Ai[k] * A_[k][j];
      }

      Ai[j] = w;
    }
  }

  /* Forward substitution: solve L * y = b. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE w = b_[i];
    int j;
    DATA_TYPE * restrict Ai = A_[i];

    for (j = 0; j < i; j++)
      w -= Ai[j] * y_[j];

    y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = _PB_N-1; i >=0; i--) {
    DATA_TYPE w = y_[i];
    int j;
    DATA_TYPE * restrict Ai = A_[i];

    for (j = i+1; j < _PB_N; j++)
      w -= Ai[j] * x_[j];

    x_[i] = w / Ai[i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
