 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* ludcmp.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Precompute constants to avoid repeated divisions in the loops. */
  const DATA_TYPE inv_fn = (DATA_TYPE)1.0 / fn;
  const DATA_TYPE b_scale = ((DATA_TYPE)0.5) * inv_fn; /* 1 / (2*n) */

  /* Initialize vectors x, y, b. */
  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      /* Original: b[i] = (i+1)/fn/2.0 + 4
       *          = (i+1) * (1/(2*fn)) + 4
       */
      b[i] = ((DATA_TYPE)(i + 1)) * b_scale + (DATA_TYPE)4.0;
    }

  /* Initialize matrix A as in the original code, but with a cheaper
   * expression. Original:
   *   A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
   * For 0 <= j < n we have (-j % n) == -j, so:
   *   A[i][j] = 1 - (j / n).
   */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A[i];

      /* Lower (and diagonal) part. */
      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)1.0 - ((DATA_TYPE)j) * inv_fn;

      /* Strict upper part. */
      for (j = i + 1; j < n; j++)
	Ai[j] = (DATA_TYPE)0.0;

      /* Exact 1.0 on diagonal (matches original behavior). */
      Ai[i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite.
   * This computes B = A * A^T, then copies B back into A.
   * The loop structure below is changed to improve cache locality
   * and enable parallelization, but the arithmetic for each
   * B[r][s] (sum over t of A[r][t] * A[s][t]) is identical.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*B_)[N] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T in a cache-friendly way:
   *   for each (r,s), B[r][s] = sum_t A[r][t] * A[s][t].
   * Outer loops over (r,s), inner loop over t for good use of
   * row-major layout of A.
   */
#pragma omp parallel for private(s,t) schedule(static) if (n >= 32)
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Br = B_[r];
      DATA_TYPE *Ar = A[r];

      for (s = 0; s < n; ++s)
	{
	  DATA_TYPE *As = A[s];
	  DATA_TYPE acc = (DATA_TYPE)0.0;

#pragma GCC ivdep
	  for (t = 0; t < n; ++t)
	    acc += Ar[t] * As[t];

	  Br[s] = acc;
	}
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Ar = A[r];
      DATA_TYPE *Br = B_[r];

#pragma GCC ivdep
      for (s = 0; s < n; ++s)
	Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

#pragma scop
  /* LU factorization without pivoting.
   *
   * The structure is similar to the original code, but the update
   * of the U-part of the row is rewritten as an outer-product style
   * update to improve data locality and reuse of A[i][k].
   */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    /* Compute L(i,0..i-1): the strictly lower triangular part of row i. */
    for (j = 0; j < i; j++) {
      DATA_TYPE *Aj = A[j];
      DATA_TYPE w = Ai[j];

      /* w -= sum_{k=0}^{j-1} L(i,k) * U(k,j) */
      for (k = 0; k < j; k++) {
        w -= Ai[k] * Aj[k];
      }

      Ai[j] = w / Aj[j];
    }

    /* Compute U(i,i..N-1): the upper triangular part of row i.
     *
     * Original code (per column j):
     *   for (j = i; j < N; ++j) {
     *     w = A[i][j];
     *     for (k = 0; k < i; ++k)
     *       w -= A[i][k] * A[k][j];
     *     A[i][j] = w;
     *   }
     *
     * This can be transformed into an outer-product update:
     *   for (k = 0; k < i; ++k) {
     *     Lik = A[i][k];
     *     for (j = i; j < N; ++j)
     *       A[i][j] -= Lik * A[k][j];
     *   }
     *
     * For each (i,j) with j >= i, we start from the original A[i][j]
     * value and subtract sum_k A[i][k] * A[k][j], which is exactly
     * the same computation. The difference is only in the order of
     * floating-point operations.
     *
     * This form improves cache behavior by:
     *   - Loading each L(i,k) once (Lik) and reusing it across many j.
     *   - Traversing row k of A (A[k][j]) sequentially in memory.
     */
    for (k = 0; k < i; k++) {
      DATA_TYPE Lik = Ai[k];
      DATA_TYPE *Ak = A[k];

#pragma GCC ivdep
      for (j = i; j < _PB_N; j++) {
        Ai[j] -= Lik * Ak[j];
      }
    }
  }

  /* Forward substitution: solve L * y = b. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE w = b[i];

    for (j = 0; j < i; j++)
      w -= Ai[j] * y[j];

    y[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = _PB_N-1; i >= 0; i--) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE w = y[i];

    for (j = i+1; j < _PB_N; j++)
      w -= Ai[j] * x[j];

    x[i] = w / Ai[i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
