void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Use local restrict-qualified pointers so the compiler knows
     that A, b, x, and y do not alias each other. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE * restrict b_ = b;
  DATA_TYPE * restrict x_ = x;
  DATA_TYPE * restrict y_ = y;

  /* Initialize vectors x, y, b. */
  for (i = 0; i < n; i++)
    {
      x_[i] = 0;
      y_[i] = 0;
      /* Keep the original arithmetic structure; the compiler
         will strength-reduce the constant division. */
      b_[i] = (i+1)/fn/2.0 + 4;
    }

  /* Initialize A as a unit-diagonal lower-triangular-like matrix. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
	Ai[j] = 0;
      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Originally:
       B = 0;
       for t
         for r
           for s
             B[r][s] += A[r][t] * A[s][t];
     which computes B = A * A^T (symmetric PSD).
     Below we compute the same B more efficiently, exploiting symmetry
     and improving locality, while preserving the exact per-(r,s)
     accumulation order over t. */

  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (* restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Build B = A * A^T.
     For each pair (r,s) with s <= r, we compute the inner product of
     row r and row s once, then mirror it to B[s][r].  The product
     A[r][t] * A[s][t] == A[s][t] * A[r][t], and for each fixed pair
     (r,s) we still accumulate t in strictly increasing order, so the
     final B is bitwise identical to the original computation. */
#ifdef _OPENMP
#pragma omp parallel for private(s,t) if (n >= 64)
#endif
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Br = B_[r];
      DATA_TYPE *Ar = A_[r];

      for (s = 0; s <= r; ++s)
	{
	  DATA_TYPE sum = 0;
	  DATA_TYPE *As = A_[s];

	  for (t = 0; t < n; ++t)
	    sum += Ar[t] * As[t];

	  /* Diagonal elements (r == s) get written twice with the same
	     value; this is harmless and avoids a branch. */
	  Br[s]    = sum;
	  B_[s][r] = sum;
	}
    }

  /* Copy B back to A. This preserves the original behaviour of
     "A := A*A^T". */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Ar = A_[r];
      DATA_TYPE *Br = B_[r];
      for (s = 0; s < n; ++s)
	Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


