  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Use restrict-qualified local pointers for better alias analysis. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE * restrict b_ = b;
  DATA_TYPE * restrict x_ = x;
  DATA_TYPE * restrict y_ = y;

#pragma scop
  /* LU factorization without pivoting: A = L * U (in-place, L has unit diag). */
  for (int i = 0; i < _PB_N; i++) {
    DATA_TYPE * restrict Ai = A_[i];

    /* Compute the L part in row i: A[i][0..i-1]. */
    for (int j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];
      /* Dot product of row i with column j over k = 0..j-1. */
      for (int k = 0; k < j; k++) {
        sum -= Ai[k] * A_[k][j];
      }
      Ai[j] = sum / A_[j][j];
    }

    /* Compute the U part in row i: A[i][i..N-1].
       Each j-iteration only depends on:
         - row i entries Ai[0..i-1] (already computed L-part), and
         - rows 0..i-1 of A (fixed for this i).
       Therefore iterations in j are independent and can be
       safely parallelized. */
#ifdef _OPENMP
#pragma omp parallel for if (n >= 64)
#endif
    for (int j = i; j < _PB_N; j++) {
      DATA_TYPE sum = Ai[j];
      for (int k = 0; k < i; k++) {
        sum -= Ai[k] * A_[k][j];
      }
      Ai[j] = sum;
    }
  }

  /* Forward substitution: solve L y = b.
     This loop is inherently sequential due to data dependence on y. */
  for (int i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = b_[i];
    DATA_TYPE * restrict Ai = A_[i];
    for (int j = 0; j < i; j++)
      sum -= Ai[j] * y_[j];
    y_[i] = sum;
  }

  /* Backward substitution: solve U x = y.
     Also inherently sequential. */
  for (int i = _PB_N-1; i >= 0; i--) {
    DATA_TYPE sum = y_[i];
    DATA_TYPE * restrict Ai = A_[i];
    for (int j = i+1; j < _PB_N; j++)
      sum -= Ai[j] * x_[j];
    x_[i] = sum / Ai[i];
  }
#pragma endscop
}


