               w -= sum_k A[i][k] * A[k][j]
             The k-iterations are independent and can be
             vectorized; OpenMP 'simd' is used as a hint. */
#pragma omp simd reduction(-:w)
          for (k_local = 0; k_local < j_local; ++k_local)
          {
            w -= Ai[k_local] * A[k_local][j_local];
