    DATA_TYPE * restrict Ai = A[i];

    /* Lower-triangular part (j < i), sequential in j. */
    for (j = 0; j < i; ++j)
    {
      DATA_TYPE w = Ai[j];

      for (k = 0; k < j; ++k)
      {
